def quarantine_files() -> list[str]:
    parent, name = os.path.split(_data_path())
    try:
        return sorted(
            f for f in os.listdir(parent or ".")
            if f.startswith(name + ".corrupt-")
        )
    except OSError:
        return []  # no data directory yet means nothing is quarantined
